import importlib

for mod in ["pypdf", "PyPDF2", "fitz", "pdfplumber", "reportlab", "pikepdf", "pdfrw"]:
    try:
        m = importlib.import_module(mod)
        print(f"{mod}: OK ({getattr(m, '__version__', 'unknown')})")
    except Exception as e:
        print(f"{mod}: MISSING ({type(e).__name__})")

import shutil

for tool in ["qpdf", "pdftk", "gs", "pdftotext", "pdfinfo", "pdfunite", "convert", "python3", "pip3", "pip"]:
    path = shutil.which(tool)
    print(f"{tool}: {path if path else 'MISSING'}")

