import subprocess, sys, os

candidates = [
    "/mlx_devbox/users/zhengxinran/playground/code_zxr/agent_safety/benchmarks/external/MSB/.venv/bin/python3",
    "/home/tiger/miniconda3/bin/python3",
    "/usr/bin/python3",
]

probe = (
    "import importlib.util, sys; "
    "mods=['pypdf','PyPDF2','fitz','pdfplumber','reportlab','pikepdf','pdfrw','pypdfium2']; "
    "print('PY', sys.version.split()[0], sys.executable); "
    "[print(' ', m, 'OK' if importlib.util.find_spec(m) else 'NO') for m in mods]"
)

for py in candidates:
    if not os.path.exists(py):
        print(py, "-> not present")
        continue
    try:
        r = subprocess.run([py, "-c", probe], capture_output=True, text=True, timeout=60)
        print(r.stdout.strip())
        if r.returncode != 0:
            print("  stderr:", r.stderr.strip()[:500])
    except Exception as e:
        print(py, "-> error", e)

